-- Phase 28.2: the casual app's new actions (docs/data-model.md). Generated by drizzle-kit; no new
-- table, so nothing new for TABLE_ACCESS (the four tables already have UPDATE) or the tenant policy.
-- - assignments.still_coming_at: her "Yes, I'm coming" in the day before (no automatic effect);
-- - workers.requests_read_at, pay_answers_read_at: the answers she's seen. DEFAULT now(), so the
--   casuals already here start with nothing new (Postgres fills the existing rows with the time of
--   this migration without rewriting the table, and forced RLS doesn't apply to ALTER TABLE);
-- - messages.shift_id: the session a message in the app is about, a composite foreign key, and
--   only on her own message in the app (messages_shift_app_only);
-- - requests: the type 'attendance' (a shift required) and the status 'withdrawn' (resolved_at
--   set, resolved_by null).
ALTER TABLE "requests" DROP CONSTRAINT "requests_type_check";--> statement-breakpoint
ALTER TABLE "requests" DROP CONSTRAINT "requests_status_check";--> statement-breakpoint
ALTER TABLE "requests" DROP CONSTRAINT "requests_shift_required";--> statement-breakpoint
ALTER TABLE "requests" DROP CONSTRAINT "requests_resolution";--> statement-breakpoint
ALTER TABLE "messages" ADD COLUMN "shift_id" uuid;--> statement-breakpoint
ALTER TABLE "workers" ADD COLUMN "requests_read_at" timestamp with time zone DEFAULT now();--> statement-breakpoint
ALTER TABLE "workers" ADD COLUMN "pay_answers_read_at" timestamp with time zone DEFAULT now();--> statement-breakpoint
ALTER TABLE "assignments" ADD COLUMN "still_coming_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "messages" ADD CONSTRAINT "messages_shift_fk" FOREIGN KEY ("firm_id","shift_id") REFERENCES "public"."shifts"("firm_id","id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "messages" ADD CONSTRAINT "messages_shift_app_only" CHECK ("messages"."shift_id" is null or ("messages"."channel" = 'app' and "messages"."direction" = 'in'));--> statement-breakpoint
ALTER TABLE "requests" ADD CONSTRAINT "requests_type_check" CHECK ("requests"."type" in ('time_change', 'swap', 'availability', 'general', 'review', 'attendance'));--> statement-breakpoint
ALTER TABLE "requests" ADD CONSTRAINT "requests_status_check" CHECK ("requests"."status" in ('open', 'approved', 'declined', 'auto_resolved', 'escalated', 'withdrawn'));--> statement-breakpoint
ALTER TABLE "requests" ADD CONSTRAINT "requests_shift_required" CHECK ("requests"."type" not in ('time_change', 'swap', 'review', 'attendance') or "requests"."shift_id" is not null);--> statement-breakpoint
ALTER TABLE "requests" ADD CONSTRAINT "requests_resolution" CHECK (("requests"."status" in ('open', 'escalated') and "requests"."resolved_at" is null and "requests"."resolved_by" is null)
        or ("requests"."status" = 'auto_resolved' and "requests"."resolved_at" is not null)
        or ("requests"."status" in ('approved', 'declined') and "requests"."resolved_at" is not null and "requests"."resolved_by" is not null)
        or ("requests"."status" = 'withdrawn' and "requests"."resolved_at" is not null and "requests"."resolved_by" is null));